WITH recent_web_events AS (SELECT * FROM web_events WHERE HOUR(event_time) BETWEEN 10 AND 18 AND (event_type = 'purchase' OR session_id IN (25, 38))), duration_sec_bucket_summary AS (SELECT CASE WHEN duration_sec >= 396 THEN 'high' WHEN duration_sec >= 179 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, AVG(duration_sec) AS avg_duration_sec, SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) AS page_view_count FROM recent_web_events GROUP BY CASE WHEN duration_sec >= 396 THEN 'high' WHEN duration_sec >= 179 THEN 'mid' ELSE 'low' END) SELECT duration_sec_bucket, page_view_count FROM duration_sec_bucket_summary WHERE avg_duration_sec < 450 ORDER BY duration_sec_bucket LIMIT 3
